import { useState } from 'react';
import {
  Button,
  Drawer,
  DrawerHeader,
  DrawerTitle,
  DrawerBody,
  DrawerCloseButton,
  Nav,
  NavItem,
  NavDivider,
} from '@jinx-ui/react';

export type NavKey = 'projects' | 'team' | 'settings' | 'logout';

interface NavMenuProps {
  onNavigate: (key: NavKey) => void;
}

export default function NavMenu({ onNavigate }: NavMenuProps) {
  const [isOpen, setIsOpen] = useState(false);

  const handleSelect = (key: NavKey) => {
    onNavigate(key);
    setIsOpen(false);
  };

  return (
    <>
      <Button variant="secondary" onClick={() => setIsOpen(true)}>
        Меню
      </Button>

      <Drawer isOpen={isOpen} onClose={() => setIsOpen(false)} placement="left">
        <DrawerHeader>
          <DrawerTitle>Навигация</DrawerTitle>
          <DrawerCloseButton onClick={() => setIsOpen(false)} />
        </DrawerHeader>
        <DrawerBody>
          <Nav>
            <NavItem onClick={() => handleSelect('projects')}>
              Проекты
            </NavItem>
            <NavItem onClick={() => handleSelect('team')}>
              Команда
            </NavItem>
            <NavItem onClick={() => handleSelect('settings')}>
              Настройки
            </NavItem>
            <NavDivider />
            <NavItem danger onClick={() => handleSelect('logout')}>
              Выйти
            </NavItem>
          </Nav>
        </DrawerBody>
      </Drawer>
    </>
  );
}

